interface Array<T> { [index: number]: T; }
type Record<K extends keyof any, T> = { [P in K]: T };
interface SymbolConstructor { readonly iterator: unique symbol; }
declare const Symbol: SymbolConstructor;
interface Promise<T> { then<U>(callback: (value: T) => U): Promise<U>; }
interface PromiseConstructor { resolve<T>(value: T): Promise<T>; }
declare const Promise: PromiseConstructor;
